import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BZO4qERu.js";const C=JSON.parse('{"title":"VS Code + Claude Code","description":"在 VS Code 中使用 Claude Code、Cline 或支持自定义 Base URL 的插件接入 Tokeness。","frontmatter":{"title":"VS Code + Claude Code","description":"在 VS Code 中使用 Claude Code、Cline 或支持自定义 Base URL 的插件接入 Tokeness。"},"headers":[],"relativePath":"integrations/vscode-claude-code.md","filePath":"integrations/vscode-claude-code.md","lastUpdated":1781532219000}'),l={name:"integrations/vscode-claude-code.md"};function i(s,e,n,r,c,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="vs-code-claude-code" tabindex="-1">VS Code + Claude Code <a class="header-anchor" href="#vs-code-claude-code" aria-label="Permalink to &quot;VS Code + Claude Code&quot;">​</a></h1><p>VS Code 里常见的 AI 编程接入方式有三种：</p><table tabindex="0"><thead><tr><th>方式</th><th>适用页面</th></tr></thead><tbody><tr><td>在 VS Code 终端里运行 Claude Code</td><td>参考 Claude Code 页面</td></tr><tr><td>使用 Cline 插件</td><td>参考 Cline 页面</td></tr><tr><td>使用其他支持自定义 Base URL 的插件</td><td>按本页通用字段配置</td></tr></tbody></table><p>Tokeness 的通用接入方式是 OpenAI 兼容接口：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://n.tokeness.io/v1</span></span></code></pre></div><h2 id="_1-在-vs-code-终端里运行-claude-code" tabindex="-1">1. 在 VS Code 终端里运行 Claude Code <a class="header-anchor" href="#_1-在-vs-code-终端里运行-claude-code" aria-label="Permalink to &quot;1. 在 VS Code 终端里运行 Claude Code&quot;">​</a></h2><p>如果你只是把 VS Code 当终端使用，配置方式和普通 Claude Code 一样：</p><ol><li>安装 Claude Code。</li><li>安装 CC Switch。</li><li>在 CC Switch 中为 Claude Code 添加 Tokeness 供应商。</li><li>开启路由模式。</li><li>在 VS Code 终端里运行 <code>claude</code>。</li></ol><p>这类场景不要在 VS Code 插件设置里重复填 Key。Claude Code 会读取自己的配置。</p><p>详见：<a href="/integrations/claude-code">Claude Code</a></p><h2 id="_2-使用-cline-插件" tabindex="-1">2. 使用 Cline 插件 <a class="header-anchor" href="#_2-使用-cline-插件" aria-label="Permalink to &quot;2. 使用 Cline 插件&quot;">​</a></h2><p>Cline 是 VS Code 插件，支持 OpenAI Compatible Provider。</p><p>字段填写：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Provider: OpenAI Compatible</span></span>
<span class="line"><span>Base URL: https://n.tokeness.io/v1</span></span>
<span class="line"><span>API Key: 你的 Tokeness API Key</span></span>
<span class="line"><span>Model ID: 从 Tokeness 模型广场复制</span></span></code></pre></div><p>详见：<a href="/integrations/cline">Cline</a></p><h2 id="_3-使用其他-vs-code-ai-插件" tabindex="-1">3. 使用其他 VS Code AI 插件 <a class="header-anchor" href="#_3-使用其他-vs-code-ai-插件" aria-label="Permalink to &quot;3. 使用其他 VS Code AI 插件&quot;">​</a></h2><p>只要插件提供这些字段，就可以尝试接入 Tokeness：</p><table tabindex="0"><thead><tr><th>插件字段</th><th>Tokeness 填写内容</th></tr></thead><tbody><tr><td>API Provider</td><td>OpenAI Compatible / OpenAI</td></tr><tr><td>API Key</td><td>Tokeness API Key</td></tr><tr><td>Base URL / API Base / Endpoint</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>Model / Model ID</td><td>Tokeness 模型广场中的完整模型名</td></tr></tbody></table><p>如果插件只支持某一家厂商登录，不支持自定义 Base URL，则不能直接接入 Tokeness。</p><h2 id="_4-claude-code-llm-gateway-说明" tabindex="-1">4. Claude Code LLM Gateway 说明 <a class="header-anchor" href="#_4-claude-code-llm-gateway-说明" aria-label="Permalink to &quot;4. Claude Code LLM Gateway 说明&quot;">​</a></h2><p>Claude Code 官方支持通过 <code>ANTHROPIC_BASE_URL</code> 接入 LLM Gateway，但这个方式要求网关暴露 Anthropic Messages 格式。</p><p>Tokeness 文档中的 Claude Code 接入默认走 CC Switch 路由模式，因为它能把 Claude Code 请求转到 OpenAI 兼容供应商。只有在你明确使用 Anthropic Messages 兼容接口时，才按 Anthropic API 页面处理。</p><p>相关页面：</p><ul><li><a href="/integrations/claude-code">Claude Code</a></li><li><a href="/integrations/anthropic-api">Anthropic API</a></li></ul><h2 id="_5-key-与额度" tabindex="-1">5. Key 与额度 <a class="header-anchor" href="#_5-key-与额度" aria-label="Permalink to &quot;5. Key 与额度&quot;">​</a></h2><p>VS Code 插件通常会读取项目上下文，消耗比普通聊天更高。</p><p>处理方式：</p><ul><li>给 VS Code 插件单独创建 Key。</li><li>给 Key 设置额度。</li><li>首次使用先跑只读任务。</li><li>大范围修改前确认 Git 工作区状态。</li><li>使用日志中按 Key 查看调用记录。</li></ul><h2 id="_6-验证" tabindex="-1">6. 验证 <a class="header-anchor" href="#_6-验证" aria-label="Permalink to &quot;6. 验证&quot;">​</a></h2><p>在插件或 Claude Code 中输入：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请只回复一句话，说明当前 VS Code 接入已经可用。</span></span></code></pre></div><p>然后检查 Tokeness 使用日志：</p><ol><li>有新请求。</li><li>Key 是 VS Code 或插件专用 Key。</li><li>模型名正确。</li><li>状态码成功。</li></ol><h2 id="_7-排查" tabindex="-1">7. 排查 <a class="header-anchor" href="#_7-排查" aria-label="Permalink to &quot;7. 排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>插件不显示 Base URL</td><td>该插件可能不支持自定义 API</td></tr><tr><td>认证失败</td><td>检查 Key、空格、是否启用</td></tr><tr><td>404 Not Found</td><td>Base URL 填 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>从模型广场重新复制模型名</td></tr><tr><td>Claude Code 无日志</td><td>检查 CC Switch 是否启用 Tokeness 和路由模式</td></tr><tr><td>插件能聊天但不能改代码</td><td>换代码能力更强的模型，或改用 Cline/Claude Code</td></tr><tr><td>消耗异常</td><td>限制上下文范围，检查是否有循环任务</td></tr></tbody></table><h2 id="外部文档" tabindex="-1">外部文档 <a class="header-anchor" href="#外部文档" aria-label="Permalink to &quot;外部文档&quot;">​</a></h2><ul><li><a href="https://docs.anthropic.com/en/docs/claude-code/llm-gateway" target="_blank" rel="noreferrer">Claude Code LLM Gateway</a></li><li><a href="https://docs.anthropic.com/zh-CN/docs/claude-code/settings" target="_blank" rel="noreferrer">Claude Code Settings</a></li><li><a href="https://docs.cline.bot/provider-config/openai-compatible" target="_blank" rel="noreferrer">Cline OpenAI Compatible Provider</a></li></ul>`,37)])])}const u=t(l,[["render",i]]);export{C as __pageData,u as default};
